unistr('<li> \696D\52D9\4F7F\7528\8005\4E5F\53EF\4EE5\77AD\89E3\4E26\7DE8\8F2F\4F4E\7A0B\5F0F\78BC\5716\8868\8655\7406\5B9A\7FA9\FF0C\4EE5\63D0\5347\696D\52D9\5F48\6027\3002\6D41\7A0B\4F7F\7528 Business Process Modeling Notation (BPMN) V2 \6A23\5F0F</li>'),
unistr('<li>\5EFA\7F6E\70BA APEX \793E\7FA4\5C08\6848\FF0C\4E26\5728\958B\6E90 MIT \6388\6B0A\4E0A\767C\884C\3002</li>'),
