'                        )',
'    union ',
'    select add_months(trunc(sysdate,''Q''), -3 - (3*level)),''QUARTER'', 100*level',
'    from dual',
'    connect by level <= (sysdate -sysdate +4)',
')',
'select sd.dt, ',
'       sd.period, ',
'       case sd.period',
'          when ''DAY''     then to_char(dt,''YYYY-MM-DD'')  || '' DAY''',
