'       ist.stsf_waiting_10pc_sec,',
'       ist.stsf_waiting_50pc_sec,',
'       ist.stsf_waiting_90pc_sec,',
'       ist.stsf_waiting_max_sec',
'  from summary_dates sd',
'  left join flow_step_stats ist',
