wwv_flow_imp_shared.create_translation(
 p_id=>wwv_flow_imp.id(13025558563416298)
,p_translated_flow_id=>100004
,p_translate_to_id=>wwv_flow_imp.id(34632505849575827.100004)
,p_translate_from_id=>wwv_flow_imp.id(34632505849575827)
,p_translate_column_id=>111
,p_translate_to_lang_code=>'de'
,p_translation_specific_to_item=>'NO'
,p_template_translatable=>'N'
,p_translate_to_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
'    <li>Ein Modell: Ein einzelnes Modell importieren, indem alle Attribute angegeben werden</li>',
'    <li>Mehrere Modelle: Importieren Sie mehrere Modelle, indem Sie eine ZIP-Datei angeben*</li>',
'</ul>',
'<p>',
'    * Die ZIP-Datei muss Folgendes enthalten:',
'    <ul>',
'        <li>Die zu importierenden BPMN-Dateien</li>',
'        <li>Eine import.json-Datei, bei der es sich um ein Array von Objekten (siehe Beispiel unten) mit den folgenden Attributen handelt:',
'            <ul>',
'                <li>dgrm_name: Der Name des Modells</li>',
'                <li>dgrm_version: Die Modellversion</li>',
'                <li>dgrm_category: Die Kategorie des Modells</li>',
'                <li>file: Der Name der bpmn-Datei im Archiv</li>',
'            </ul>',
'        </li>',
'    </ul>',
unistr('Beispiel f\00FCr eine import.json-Datei mit zwei Modellen<br>'),
'<pre><code>[',
'{',
'    "dgrm_name": "Die Pizza-Kollaboration",',
'    "dgrm_version": "0",',
'    "dgrm_status": "draft",',
'    "dgrm_category": Null,',
'    "file": "The Pizza Collaboration_0.bpmn"',
'  },',
'  {',
'    "dgrm_name": "Feiertage",',
'    "dgrm_version": "0",',
'    "dgrm_status": "draft",',
'    "dgrm_category": Null,',
'    "file": "Holidays_0.bpmn"',
'  }',
']',
'</code></pre>',
'</p>'))
,p_translate_from_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
'    <li>One Model: Import a single model by providing all the attributes</li>',
'    <li>Multiple Models: Import several models by providing a zip file*</li>',
'</ul>',
'<p>',
'    * The zip file must contain:',
'    <ul>',
'        <li>The bpmn files to import</li>',
'        <li>An import.json file which is an array of objects (see example below) with the following attributes:',
'            <ul>',
'                <li>dgrm_name: The model''s name</li>',
'                <li>dgrm_version: The model''s version</li>',
'                <li>dgrm_category: The model''s category</li>',
'                <li>file: The name of the bpmn file in the archive</li>',
'            </ul>',
'        </li>',
'    </ul>',
'Example of an import.json file with two models<br>',
'<pre><code>[',
'  {',
'    "dgrm_name": "The Pizza Collaboration",',
'    "dgrm_version": "0",',
'    "dgrm_status": "draft",',
'    "dgrm_category": null,',
'    "file": "The Pizza Collaboration_0.bpmn"',
'  },',
'  {',
'    "dgrm_name": "Holidays",',
'    "dgrm_version": "0",',
'    "dgrm_status": "draft",',
'    "dgrm_category": null,',
'    "file": "Holidays_0.bpmn"',
'  }',
']',
'</code></pre>',
'</p>'))
);
