,p_translate_to_lang_code=>'de'
,p_translation_specific_to_item=>'NO'
,p_template_translatable=>'N'
,p_translate_to_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Wenn Sie dieses Kontrollk\00E4stchen aktivieren, speichert die Anwendung Ihren Benutzernamen in einem persistenten Browsercookie namens "LOGIN_USERNAME_COOKIE".'),
unistr('Wenn Sie das n\00E4chste Mal zur Anmeldeseite gehen,'),
unistr('wird das Feld "Benutzername" automatisch mit diesem Wert aufgef\00FCllt.'),
'</p>',
'<p>',
unistr('Wenn Sie dieses Kontrollk\00E4stchen deaktivieren und Ihr Benutzername bereits im Cookie gespeichert ist,'),
unistr('wird es von der Anwendung mit einem leeren Wert \00FCberschrieben.'),
unistr('Sie k\00F6nnen auch die Entwicklertools Ihres Browsers verwenden, um das Cookie vollst\00E4ndig zu entfernen.'),
'</p>'))
,p_translate_from_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'If you select this checkbox, the application will save your username in a persistent browser cookie named "LOGIN_USERNAME_COOKIE".',
'When you go to the login page the next time,',
'the username field will be automatically populated with this value.',
'</p>',
'<p>',
'If you deselect this checkbox and your username is already saved in the cookie,',
'the application will overwrite it with an empty value.',
'You can also use your browser''s developer tools to completely remove the cookie.',
'</p>'))
);
