'       ist.stpr_duration_50pc_sec,',
'       ist.stpr_duration_90pc_sec,',
'       ist.stpr_duration_max_sec',
'  from summary_dates sd',
'  left join flow_instance_stats ist',
'    on sd.dt     = ist.stpr_period_start',
'   and sd.period = ist.stpr_period',
