unistr('   * zip \D30C\C77C\C5D0\B294 \B2E4\C74C\C774 \D3EC\D568\B418\C5B4\C57C \D569\B2C8\B2E4.'),
'    <ul>',
unistr('        <li>\C784\D3EC\D2B8\D560  bpmn \D30C\C77C\B4E4</li>'),
unistr('        <li>\B2E4\C74C \C18D\C131\C744 \AC00\C9C4 \AC1D\CCB4 \BC30\C5F4(\C544\B798 \C608 \CC38\C870)\C778 import.json \D30C\C77C.'),
'            <ul>',
unistr('                <li>dgrm_name: \BAA8\B378\C758 \C774\B984</li>'),
unistr('                <li>dgrm_version: \BAA8\B378\C758 \BC84\C804</li>'),
unistr('                <li>dgrm_category: \BAA8\B378\C758 \BC94\C8FC</li>'),
unistr('                <li>file: \C544\CE74\C774\BE0C\C5D0 \C788\B294 bpmn \D30C\C77C\C758 \C774\B984</li>'),
'            </ul>',
'        </li>',
'    </ul>',
unistr('\B450 \AC1C\C758 \BAA8\B378\C774 \C788\B294 import.json \D30C\C77C\C758 \C608<br>'),
'<pre><code>[',
'{',
unistr('     "dgrm_name": "\D53C\C790 \D611\B825",'),
'    "dgrm_version": "0",',
unistr('    "dgrm_status": "\CD08\C548",'),
'    "dgrm_category": null,',
unistr('    "file": "\D53C\C790 Collaboration_0.bpmn"'),
'  },',
'  {',
unistr('    "dgrm_name": "\D734\C77C",'),
'    "dgrm_version": "0",',
unistr('    "dgrm_status": "\CD08\C548",'),
'    "dgrm_category": null,',
'    "file": "Holidays_0.bpmn"',
'  }',
']',
'</code></pre>',
'</p>'))
,p_translate_from_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
'    <li>One Model: Import a single model by providing all the attributes</li>',
'    <li>Multiple Models: Import several models by providing a zip file*</li>',
'</ul>',
'<p>',
'    * The zip file must contain:',
'    <ul>',
'        <li>The bpmn files to import</li>',
'        <li>An import.json file which is an array of objects (see example below) with the following attributes:',
'            <ul>',
'                <li>dgrm_name: The model''s name</li>',
'                <li>dgrm_version: The model''s version</li>',
'                <li>dgrm_category: The model''s category</li>',
'                <li>file: The name of the bpmn file in the archive</li>',
'            </ul>',
'        </li>',
'    </ul>',
'Example of an import.json file with two models<br>',
'<pre><code>[',
'  {',
'    "dgrm_name": "The Pizza Collaboration",',
'    "dgrm_version": "0",',
'    "dgrm_status": "draft",',
'    "dgrm_category": null,',
'    "file": "The Pizza Collaboration_0.bpmn"',
'  },',
'  {',
'    "dgrm_name": "Holidays",',
'    "dgrm_version": "0",',
'    "dgrm_status": "draft",',
'    "dgrm_category": null,',
'    "file": "Holidays_0.bpmn"',
'  }',
']',
'</code></pre>',
'</p>'))
);
