'     , stsf_objt_bpmn_id',
'     , sum(stsf_completed)',
'     , avg(stsf_duration_10pc_sec)',
'     , avg(stsf_duration_50pc_sec)',
'     , avg(stsf_duration_90pc_sec)',
'     , max(stsf_duration_max_sec)',
'from  flow_step_stats stsf',
'left join flow_objects objt',
'  on objt.objt_dgrm_id = stsf.stsf_dgrm_id',
