'where stsf_period_start >= sysdate - :P16_period',
'and stsf_period = ''DAY''',
'and stsf_dgrm_id = :P16_DGRM_ID',
'group by stsf_objt_bpmn_id||'' (''||stsf_tag_name || '')'', objt.objt_name, stsf_objt_bpmn_id',
'order by max(stsf_duration_max_sec) desc'))
